class sample
{
    public int i;
    public int j;
    public void fun(int i, int j)
    {
        this.i = i;
        this.j = j;
    }
}
class Program
{
    static void Main(string[] args)
    {
        sample s = new sample();
        s.i = 1;
        s.j = 2;
        s.fun(10, 20);
        Console.WriteLine(s.i + " " + s.j);
    }
}

class z
{
    public int X;
    public int Y;
    public const int c1 = 5;
    public const int c2 = c1 * 25;
    public void set(int a, int b)
    {
        X = a;
        Y = b;
    }
}
class Program
{
    static void Main(string[] args)
    {
        z s = new z();
        s.set(10, 20);
        Console.WriteLine(s.X + " " + s.Y);
        Console.WriteLine(z.c1 + " " + z.c2);
    }
}

class z
{
    public string name1;
    public string address;
    public void show()
    {
        Console.WriteLine("{0} is in {1}", name1, address);
    }
}
class Program
{
    static void Main(string[] args)
    {
        z n = new z();
        n.name1 = "harsh";
        n.address = "new delhi";
        n.show();
    }
}

